import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Sidebar from "../../components/Sidebar";
import "../../styles/Lesson.css";

// Economics lessons with videos
const ECONOMICS_LESSONS = [
  {
    lesson_number: 1,
    title: "Economic Fundamentals",
    videos: [
      { id: 1, title: "What is Economics?", url: "https://www.youtube.com/embed/3ez10ADR_gM" },
      { id: 2, title: "Scarcity & Choice", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 3, title: "Opportunity Cost", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 4, title: "Production Possibilities", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 5, title: "Economic Systems", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }
    ]
  },
  {
    lesson_number: 2,
    title: "Supply & Demand",
    videos: [
      { id: 1, title: "Understanding Demand", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 2, title: "Understanding Supply", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 3, title: "Market Equilibrium", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 4, title: "Price Controls", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 5, title: "Elasticity", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }
    ]
  },
  {
    lesson_number: 3,
    title: "Consumer Behavior",
    videos: [
      { id: 1, title: "Utility & Preferences", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 2, title: "Budget Constraints", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 3, title: "Income & Substitution Effects", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 4, title: "Behavioral Economics", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 5, title: "Consumer Decisions", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }
    ]
  },
  {
    lesson_number: 4,
    title: "Production & Costs",
    videos: [
      { id: 1, title: "Factors of Production", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 2, title: "Short Run vs Long Run", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 3, title: "Cost Curves", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 4, title: "Economies of Scale", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 5, title: "Productivity", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }
    ]
  },
  {
    lesson_number: 5,
    title: "Market Structures",
    videos: [
      { id: 1, title: "Perfect Competition", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 2, title: "Monopoly", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 3, title: "Oligopoly", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 4, title: "Monopolistic Competition", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 5, title: "Game Theory", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }
    ]
  },
  {
    lesson_number: 6,
    title: "Labor Economics",
    videos: [
      { id: 1, title: "Demand for Labor", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 2, title: "Supply of Labor", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 3, title: "Wage Determination", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 4, title: "Unemployment", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 5, title: "Unions & Labor Markets", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }
    ]
  },
  {
    lesson_number: 7,
    title: "Macroeconomics Basics",
    videos: [
      { id: 1, title: "GDP & National Income", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 2, title: "Inflation", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 3, title: "Unemployment", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 4, title: "Business Cycles", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 5, title: "Aggregate Demand & Supply", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }
    ]
  },
  {
    lesson_number: 8,
    title: "Fiscal & Monetary Policy",
    videos: [
      { id: 1, title: "Government Spending", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 2, title: "Taxation", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 3, title: "Money Supply", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 4, title: "Central Banking", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 5, title: "Interest Rates", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }
    ]
  },
  {
    lesson_number: 9,
    title: "International Economics",
    videos: [
      { id: 1, title: "Comparative Advantage", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 2, title: "International Trade", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 3, title: "Exchange Rates", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 4, title: "Global Finance", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 5, title: "Trade Agreements", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }
    ]
  },
  {
    lesson_number: 10,
    title: "Applied Economics & Future",
    videos: [
      { id: 1, title: "Environmental Economics", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 2, title: "Development Economics", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 3, title: "Behavioral Economics", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 4, title: "Innovation & Technology", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 5, title: "Economic Challenges", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }
    ]
  }
];

export default function Economics() {
  const [sub, setSub] = useState(null);
  const [loading, setLoading] = useState(true);
  const [lessons, setLessons] = useState([]);
  const navigate = useNavigate();
  const user = JSON.parse(localStorage.getItem("user")) || null;

  useEffect(() => {
    setSub("Economics");
    setLessons(ECONOMICS_LESSONS);
    setLoading(false);
  }, []);

  if (loading) return <div>Loading...</div>;

  const handleLessonClick = (lesson) => {
    navigate("/lesson", { state: { lesson } });
  };

  return (
    <div className="page-container">
      <Sidebar />
      <div className="content">
        <h1>{sub}</h1>
        <div className="lessons-grid">
          {lessons.map((lesson) => (
            <div key={lesson.lesson_number} className="lesson-card" onClick={() => handleLessonClick(lesson)}>
              <h3>Lesson {lesson.lesson_number}</h3>
              <p>{lesson.title}</p>
              <span className="video-count">{lesson.videos.length} videos</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
